-- Explicitly synthetic complete G1 source/native DATA in hosted fresh DB ONLY.
-- No current source authority, native capability or production readiness.
create function pg_temp.g1_sha(t text)returns text language sql immutable as $$select encode(sha256(convert_to(t,'UTF8')),'hex')$$;
create function pg_temp.g1_canonical(j jsonb)returns text language sql immutable as $$select private_fcf_future_import.canonical_json(j)$$;
create function pg_temp.g1_assert(v boolean,m text)returns void language plpgsql as $$begin if v is not true then raise exception 'G1 TEST: %',m;end if;end$$;
create function pg_temp.g1_reject(command text,label text,expected_error text default null)returns void language plpgsql as $$begin begin execute command;raise exception 'G1 TEST: accepted %',label;exception when others then if sqlerrm like 'G1 TEST:%'or sqlerrm not like'FCF_TARGET:%'and sqlerrm not like'FCF_G1_9410:%'and sqlerrm not like'FCF_G1_SUPPLEMENT:%'and sqlerrm not like'HISTORICAL_POLICY:%'or expected_error is not null and position(expected_error in sqlerrm)=0 then raise;end if;end;end$$;
-- TEST ONLY diagnostic decomposition of the import's first bundled calendar
-- assertion. The production gate stays unchanged; these name the exact failed
-- fixture prerequisite before the fixed test invokes it.
select pg_temp.g1_assert((select count(*)=240 from g1_fixture),'calendar diagnostic expected 240 mapped source rows');
select pg_temp.g1_assert((select count(*)=30 from rounds where competition_id=783),'calendar diagnostic expected 30 target rounds');
select pg_temp.g1_assert((select count(*)=240 from matches m join rounds r on r.id=m.round_id where r.competition_id=783),'calendar diagnostic expected 240 target matches');
select pg_temp.g1_assert((select count(distinct(home,away))=240 from g1_fixture),'calendar diagnostic expected 240 unique directed pairs');
select pg_temp.g1_assert(not exists(select 1 from g1_fixture e left join matches m on m.id=e.mid where m.id is null),'calendar diagnostic mapped match missing');
select pg_temp.g1_assert(not exists(select 1 from g1_fixture e join matches m on m.id=e.mid where m.round_id<>e.rid),'calendar diagnostic match-to-round ID mismatch');
select pg_temp.g1_assert(not exists(select 1 from g1_fixture e join rounds r on r.id=e.rid where r.competition_id<>783),'calendar diagnostic round competition mismatch');
select pg_temp.g1_assert(not exists(select 1 from g1_fixture e join rounds r on r.id=e.rid where r.season<>'2026/27'),'calendar diagnostic round season mismatch');
select pg_temp.g1_assert(not exists(select 1 from g1_fixture e join rounds r on r.id=e.rid where r.number<>(e.doc->>'round')::int),'calendar diagnostic source-to-round number mismatch');
select pg_temp.g1_assert(not exists(select 1 from g1_fixture e join matches m on m.id=e.mid where e.home=e.away or m.home_team_id<>e.home or m.away_team_id<>e.away),'calendar diagnostic source-to-native club mapping mismatch');
select pg_temp.g1_assert(not exists(select 1 from g1_fixture e join matches m on m.id=e.mid where m.zapisnik_id is not null and m.zapisnik_id<>e.id),'calendar diagnostic report ID mismatch');
select pg_temp.g1_assert(not exists(select 1 from g1_fixture e join matches m on m.id=e.mid where m.imported_at is not null and e.doc->>'statisticsStatus'='pending'),'calendar diagnostic imported pending source row');
select pg_temp.g1_assert(not exists(select 1 from g1_fixture where id!~'^es[1-9][0-9]*$'),'calendar diagnostic malformed source ID');
select pg_temp.g1_assert(not exists(select 1 from g1_fixture where substring(id from 3)::bigint not between 4109388 and 4109627),'calendar diagnostic source ID outside fixed G1 range');
select pg_temp.g1_assert(exists(select 1 from g1_fixture e join matches m on m.id=e.mid join rounds r on r.id=e.rid where e.id='es4109404' and e.mid=321663 and m.zapisnik_id='es4109404' and r.competition_id=783 and r.season='2026/27' and r.number=3 and m.home_team_id=8575 and m.away_team_id=8576),'calendar diagnostic expected exact reviewed 4109404 cleanup placeholder mapping');
create temporary table g1_rollout(v jsonb);
do $packet$declare v jsonb;p jsonb;b jsonb;cap jsonb;cb jsonb;stored private_fcf_future_history.cleanup_receipt%rowtype;mp jsonb;fs jsonb;data jsonb;sup jsonb:='{}';s jsonb;q text;f jsonb;native matches;projection jsonb;scores jsonb;privacy_keys text[];policy private_historical_statistics.policies%rowtype;stamp timestamptz:=clock_timestamp();begin
 select d into data from g1_source;select jsonb_agg(jsonb_set(doc,'{source,capturedUTC}',to_jsonb(stamp-interval'2 minutes'))order by id)into fs from g1_fixture;
 select *into stored from private_fcf_future_history.cleanup_receipt where singleton;
 cb:=jsonb_build_object('phase','applied','sourceCommit',stored.main_commit,'preparedUTC',stamp,'beforeImageText',stored.before_image_text,'beforeSha256',stored.before_sha256,'policyHashes',stored.policy_hashes,'prepareArtifact',jsonb_build_object('synthetic',true),'appliedReceipt',jsonb_build_object('result',stored.result),'originals',(select jsonb_agg(jsonb_build_object('competitionSlug',pol.document->>'competitionSlug','sourceMatchId',e->>'sourceMatchId','policyId',pol.id,'policySha256',pol.policy_sha256,'receipt',jsonb_build_object('rawSha256',e->>'rawSha256'),'fixture',(e-array['rawSha256','reasonCode'])||jsonb_build_object('season','2026/27')))from private_historical_statistics.policies pol cross join lateral jsonb_array_elements(pol.document->'entries')e where pol.document->>'sourcePolicy'='es-fcf-six-reviewed-history-v1'));
 select *into policy from private_historical_statistics.policies where document->>'competitionSlug'='es-ct-segona-g1'and document->>'sourcePolicy'='es-fcf-six-reviewed-history-v1';
 cap:=(data->'currentCapture')||jsonb_build_object('firstSourceUTC',stamp-interval'15 minutes','lastSourceEndedUTC',stamp-interval'2 minutes','sourceFreshUntil',stamp-interval'15 minutes'+interval'24 hours');
 b:=(data->'binding')||jsonb_build_object('currentCapture',cap,'firstSourceUTC',cap->'firstSourceUTC','sourceFreshUntil',cap->'sourceFreshUntil');b:=b||jsonb_build_object('sourceFingerprintSha256',pg_temp.g1_sha(pg_temp.g1_canonical(jsonb_build_object('targetSlug','es-ct-segona-g1','currentCapture',cap,'policyHashes',b->'policyHashes','fixtures',fs))));
 for q in select unnest(array['4109409','4109410'])loop
  s:=case when q='4109409'then private_fcf_g1_supplement.policy()else private_fcf_g1_9410.policy()end;select *into native from matches where id=(select mid from g1_fixture where id='es'||q);
  sup:=sup||jsonb_build_object(q,jsonb_build_object('schemaVersion',1,'kind',case when q='4109409'then'fcf-g1-native-supplement'else'fcf-g1-native-supplement-4109410'end,'policyId',s->>'id','policySha256',case when q='4109409'then'a9141400858c80322b6cb12b13c54a5dde45e93f080b4fe0b644dce513657ee7'else'7e72c15684c02ce7556921224971bc0f302acc19c786852f92920832f318eaac'end,'approvalReference',s->>'approvalReference','approvedOriginalSha256',s->>'approvedOriginalSha256','fixture',s->'fixture','native',jsonb_build_object('matchId',native.id,'roundId',native.round_id,'homeTeamId',native.home_team_id,'awayTeamId',native.away_team_id),'sourceCommit',b->>'sourceCommit','sourceFingerprintSha256',b->>'sourceFingerprintSha256','prelaunch',jsonb_build_object('kind','exact-legacy-placeholder-v1','beforeImageText',to_jsonb(native)::text,'beforeSha256',pg_temp.g1_sha(to_jsonb(native)::text))));
 end loop;
 select array_agg(distinct k order by k)into privacy_keys from(select public.anonimizacijski_kljuc((select country_id::text from competitions where id=783)||'|reg|'||(x->>'regSt'))k from jsonb_array_elements(fs)fixture_row(doc)cross join lateral jsonb_array_elements(case when fixture_row.doc->>'statisticsStatus'='available'then fixture_row.doc->'appearances'else'[]'::jsonb end)x union select public.anonimizacijski_kljuc((select country_id::text from competitions where id=783)||'|'||(x->>'ime'))from jsonb_array_elements(fs)fixture_row(doc)cross join lateral jsonb_array_elements(case when fixture_row.doc->>'statisticsStatus'='available'then fixture_row.doc->'appearances'else'[]'::jsonb end)x)keys;
 projection:=private_fcf_g1_readonly.capture('es-ct-segona-g1',privacy_keys);scores:=jsonb_build_object('selectedG1',private_fcf_g1_native800.score_state(783),'offTargetG9',private_fcf_g1_native800.score_state(797));perform pg_temp.g1_assert((scores#>>'{selectedG1,count}')::int>0 and(scores#>>'{offTargetG9,count}')::int>0,'both genuinely stored nonzero synthetic score vectors before import');
 mp:=jsonb_build_object('schemaVersion',1,'kind','fcf-native-target-mapping','targetSlug','es-ct-segona-g1','sourceCommit',repeat('b',40),'captureSourceCommit',b->>'sourceCommit','auditedUTC',stamp,'sourceFingerprintSha256',b->>'sourceFingerprintSha256','databaseSha256',repeat('e',64),'existingExceptionBindingsSha256',repeat('f',64),'mappings',(select jsonb_agg(jsonb_build_object('nativeClubId',club,'nativeCategoryId',category,'teamId',team,'sourceName',source_name,'canonicalTeamName',canonical_name)order by club,category)from g1_clubs),'fixtures',(select jsonb_agg(jsonb_build_object('sourceMatchId',id,'sourceRound',(doc->>'round')::int,'matchId',mid,'roundId',rid,'homeTeamId',home,'awayTeamId',away)order by id)from g1_fixture));
 p:=jsonb_build_object('schemaVersion',1,'kind','fcf-g1-native800-import-packet','protocol','fcf-g1-native800-v1','targetSlug','es-ct-segona-g1','sourceCommit',repeat('b',40),'captureSourceCommit',b->>'sourceCommit','auditedUTC',stamp,'cleanupBinding',cb,'supplementalBindings',sup,'databaseInventory',projection->'databaseInventory','identityPlan',jsonb_build_object('mappingText',mp::text,'mappingSha256',pg_temp.g1_sha(mp::text)),'scoreBeforeimages',scores,'nativeSnapshotText',projection->>'dependencySnapshotText','nativeSnapshotSha256',projection->>'dependencySnapshotSha256','target',jsonb_build_object('sourceEvidence',b,'competitionId',783,'competitionSlug','es-ct-segona-g1','sourceCode','4109388-4109627','season','2026/27','policyId',policy.id,'policySha256',policy.policy_sha256,'sourcePolicyId','es-fcf-six-reviewed-history-v1','fixtures',fs,'clubs',data->'clubs','verifiedKeeperClubs',data->'verifiedKeeperClubs','classificationCounts',data->'classificationCounts','unresolvedReportIds','[]'::jsonb));
 v:=jsonb_build_object('schemaVersion',1,'kind','fcf-g1-native800-import-rollout','protocol','fcf-g1-native800-v1','targetSlug','es-ct-segona-g1','sourceCommit',repeat('b',40),'execution',jsonb_build_object('repository','Lovro-splichal-orhanizagi/mnzgorenjska','ref','refs/heads/main','commit',repeat('b',40),'runId','90000001003','runAttempt','1'),'targetPacketText',p::text,'targetPacketSha256',pg_temp.g1_sha(p::text),'inventoryBinding',b,'cleanupBinding',cb,'supplementalBindings',sup,'identityPlan',p->'identityPlan','scoreBeforeimages',scores,'nativeSnapshotText',p->>'nativeSnapshotText','nativeSnapshotSha256',p->>'nativeSnapshotSha256','readiness',null);insert into g1_rollout values(v);
end$packet$;
create function pg_temp.g1_attest(v jsonb,stage text)returns text language sql as $$select jsonb_build_object('schemaVersion',1,'kind','fcf-g1-native800-stage-attestation','stage',stage,'targetSlug','es-ct-segona-g1','sourceCommit',v->>'sourceCommit','execution',v->'execution','rolloutSha256',pg_temp.g1_sha(v::text),'sourceBindingSha256',pg_temp.g1_sha(pg_temp.g1_canonical(v->'inventoryBinding')),'counter',jsonb_build_object('schemaVersion',1,'kind','fcf-refresh800-ledger','profileSha256','4b379dadb577fc0269dad744782faebb9c771fd3c7de13e492595fbac0584eeb','anchor',v#>'{inventoryBinding,anchor}','actualSourceGETs',541,'maximumCumulativeSourceGETs',800,'probeAttempts',1,'lastSourceEndedUTC',v#>'{inventoryBinding,currentCapture,lastSourceEndedUTC}','historySha256',repeat('f',64),'sourceRefusal',false,'verifiedUTC',clock_timestamp()))::text$$;
create function pg_temp.g1_import(v jsonb)returns jsonb language plpgsql as $$declare t text:=pg_temp.g1_attest(v,'import');begin return public.fcf_g1_native800_import(v::text,pg_temp.g1_sha(v::text),t,pg_temp.g1_sha(t));end$$;
create function pg_temp.g1_mutant(v jsonb,key text,value jsonb)returns jsonb language plpgsql as $$declare p jsonb;begin p:=jsonb_set((v->>'targetPacketText')::jsonb,array[key],value);return jsonb_set(v,array[key],value)||jsonb_build_object('targetPacketText',p::text,'targetPacketSha256',pg_temp.g1_sha(p::text));end$$;
select pg_temp.g1_assert(public.fcf_g1_native800_receipt()is null,'missing receipt is UNKNOWN, no fake success');
select pg_temp.g1_reject(format('select pg_temp.g1_import(%L::jsonb)',jsonb_set(v,'{inventoryBinding,protocol}','"future-g1-after-failed-g1-v1"')),'legacy retag')from g1_rollout;
select pg_temp.g1_reject(format('select pg_temp.g1_import(%L::jsonb)',pg_temp.g1_mutant(v,'scoreBeforeimages',jsonb_set(v->'scoreBeforeimages','{offTargetG9,snapshotText}','"[]"'))),'G9 exact raw beforeimage drift')from g1_rollout;
select pg_temp.g1_reject(format('select pg_temp.g1_import(%L::jsonb)',jsonb_set(v,'{execution,runAttempt}','"2"')),'attempt2')from g1_rollout;
select pg_temp.g1_reject('select public.fcf_g1_native800_check(''{}'',''bad'',true,''{}'',''bad'')','activation true in importcheck');
select pg_temp.g1_assert((pg_temp.g1_import(v)->>'stage')='imported','real new G1 import')from g1_rollout;select 'FCF_G1_NATIVE800_IMPORT_PASS';
select pg_temp.g1_assert((pg_temp.g1_import(v)->>'noOp')::boolean,'exact import no-op')from g1_rollout;select 'FCF_G1_NATIVE800_NOOP_PASS';
select pg_temp.g1_assert(public.fcf_g1_native800_receipt()->>'kind'='fcf-g1-native800-import-receipt','exact committed readback');select 'FCF_G1_NATIVE800_READBACK_PASS';
create function pg_temp.g1_check(v jsonb)returns jsonb language plpgsql as $$declare t text:=pg_temp.g1_attest(v,'check');begin return public.fcf_g1_native800_check(v::text,pg_temp.g1_sha(v::text),false,t,pg_temp.g1_sha(t));end$$;
select pg_temp.g1_assert(pg_temp.g1_check(v)->>'canonicalVerified'='true','current import state check')from g1_rollout;select 'FCF_G1_NATIVE800_CHECK_PASS';
select pg_temp.g1_assert((select count(*)from matches where zapisnik_id in('es4109409','es4109410')and home_goals is null and away_goals is null and statistics_status='unavailable_historical')=2,'both actual durable unknown results remain literal NULL');
-- Coherent fingerprint after quoted-counter mutation tests type, not stale SHA.
do $typed$declare v jsonb;b jsonb;fs jsonb;begin select x.v into v from g1_rollout x;fs:=(v->>'targetPacketText')::jsonb#>'{target,fixtures}';b:=jsonb_set(v->'inventoryBinding','{currentCapture,newSourceGETs}','"240"'::jsonb);b:=b||jsonb_build_object('sourceFingerprintSha256',pg_temp.g1_sha(pg_temp.g1_canonical(jsonb_build_object('targetSlug','es-ct-segona-g1','currentCapture',b->'currentCapture','policyHashes',b->'policyHashes','fixtures',fs))));perform pg_temp.g1_reject(format('select private_fcf_g1_native800.source_binding(%L::jsonb,%L::jsonb)',b,fs),'coherent quoted capture counter','complete actual full240 capture binding');end$typed$;
select pg_temp.g1_reject('insert into appearances(match_id,player_id,team_id)select m.id,(select min(id)from players where competition_id=783),m.home_team_id from matches m where zapisnik_id=''es4109410''','9410 individual insert','individual statistics unavailable');
select pg_temp.g1_reject('update matches set home_goals=1 where zapisnik_id=''es4109410''','9410 NULL marker update','installed match immutable');
select pg_temp.g1_reject(format('select pg_temp.g1_import(%L::jsonb)',jsonb_set(v,'{execution,runId}','"90000001004"')),'different saved import execution','exact same saved payload/state')from g1_rollout;
savepoint g1_anon_role;
set local role anon;
select set_config('request.jwt.claim.role','service_role',true);
do $role$declare held boolean:=false;begin begin perform public.fcf_g1_native800_import('{}',repeat('a',64),'{}',repeat('a',64));exception when insufficient_privilege then held:=true;end;if not held then raise exception 'G1 TEST: anon JWT spoof entered writer';end if;end$role$;
rollback to savepoint g1_anon_role;
select 'FCF_G1_NATIVE800_IMPORT_NEGATIVES_PASS';
savepoint g1_service_private;
set local role service_role;
do $private_role$declare held boolean:=false;begin begin perform private_fcf_g1_native800.install_supplements('{}');exception when insufficient_privilege then held:=true;end;if not held then raise exception 'G1 TEST: service entered private installer';end if;end$private_role$;
rollback to savepoint g1_service_private;
